const LEON_SP_ARTWORK_WEBP_BASE64_PARTS = [
  "",
  "",
  "",
  "",
  "
",
  "
",
  "",
  "",
];

const HERO_SP_ARTWORK_SOURCE_BY_ID = new Map<number, string>([
  [6, `data:image/webp;base64,${LEON_SP_ARTWORK_WEBP_BASE64_PARTS.join("")}`],
]);

export function getHeroSpArtworkSource(heroId: number) {
  return HERO_SP_ARTWORK_SOURCE_BY_ID.get(heroId) ?? null;
}
